 verify_csrf(); $name=trim($_POST['name']??''); $email=trim(strtolower($_POST['email']??'')); $password=$_POST['password']??''; $confirm=$_POST['confirm_password']??'';
 if(strlen($name)<2) $error='Please enter your name.'; elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)) $error='Enter a valid email address.'; elseif(strlen($password)<8) $error='Your password must contain at least 8 characters.'; elseif($password!==$confirm) $error='The passwords do not match.';
 else {try{$stmt=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();session_regenerate_id(true);$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'student'];flash('success','Your account has been created. Welcome to SomaliLingua!');redirect('pages/dashboard.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'An account with this email already exists.':'Could not create the account. Please try again.';}}
}
